   "id": "xz-9ie17j",
   "module": "判断推理",
   "source": "2016年423联考《行测》题 · 第15题",
   "question": "诱发运动是指由于一个物体的运动使其相邻的一个静止物体产生运动的错觉现象。\n根据上述定义，下列属于诱发运动的是：",
   "options": [
    "A. 在黑板前点燃一支蜡烛，并注视着烛光会看到烛光在运动",
    "B. 多张图片按一定空间间隔与时间距离相继呈现形成电影",
    "C. 注视瀑布的某一处，再看周围的树木，会觉得树木在向上飞升",
    "D. 当我们注视夜空时，会看到月亮在动，而云是静止的"
   ],
   "answer": "D",
   "analysis": "第一步：找到定义关键词。\n“由于一个物体的运动”、“使其相邻的一个静止物体产生运动的错觉”。\n第二步：逐一分析选项。\nA项：烛光本来就会随风摇动，并不存在让一个静止的物体产生运动的错觉，不符合“使其相邻的一个静止物体产生运动的错觉”，不符合定义，排除；\nB项：电影的动态画面是多张图片连续切换的结果，而不是一个物体的运动使相邻静止的物体产生运动的错觉，不符合“由于一个物体的运动”、“使其相邻的一个静止物体产生运动的错觉”，不符合定义，排除；\nC项：在注视瀑布后，瀑布向下运动的影像会暂时留在视网膜上，当视线转移到静止的树木时，大脑会误判为树木在向上运动，是运动后效。之所以会觉得树木朝着瀑布向上飞升，原因是长时间注视，不符合“使其相邻的一个静止物体产生运动的错觉”，不符合定义，排除；\nD项：注视夜空时会看到月亮在动，而云是静止的，之所以出现这种情况是因为云在运动，给人产生了错觉误以为月亮在运动，符合“由于一个物体的运动”、“使其相邻的一个静止物体产生运动的错觉”，符合定义，当选。\n故正确答案为D。",
   "exam": "tianjin",
   "year": 2016
