   "source": "2016年423联考《行测》题 · 第22题",
   "question": "X分子具有Y结构，串联起了大量的原子，由该分子组成的某种物质在同类型的物质中具有很强的导热性。很明显，分子内包含大量原子是使得该物质拥有极强的导热性所必不可少的。\n以下哪项如果为真，最能削弱上述结论？",
   "options": [
    "A. 有的分子拥有别的结构，也串联起了大量的原子，并拥有很强的导热性",
    "B. 有的物质导热性不强，但是它的分子中包含了大量的原子",
    "C. 有的物质导热性很强，但是其分子不具备Y结构",
    "D. 有的物质导热性不强，但是其分子具备类似的结构"
   ],
