   "source": "2017年422联考《行测》题 · 第6题",
   "question": "自我效能感是个体对自己能否成功操作某一行为达到某种预期效果的主观预期和推断。当面临困难任务时，低自我效能感的人比高自我效能感的人更集中于问题存在的障碍、失败影响以及个人缺陷上。\n根据上述定义，下列选项属于低自我效能感表现的是：",
