   "question": "数据挖掘（Data mining）是指从大量的存储数据中利用统计、情报检索、模式识别、在线分析处理和专家系统（依靠过去的经验）等方法或技术，发现隐含在其中、事先不知道但又是潜在有用的信息和知识的信息处理过程。\n根据上述定义，下列选项不属于数据挖掘应用的是：",
   "options": [
    "A. 某全球零售企业在分析上一年度消费者购物行为后推出“img/formula-53e3ef2bd78f04b7.webp”促销举措，使得二者销量大幅增加",
    "B. 某国际快递和物流公司使用RFID（无线射频识别）技术在不同时间点跨境全程监控和调整药品装运的温度",
    "C. 某大型网上书店在客户选购一种图书时，推出“购买该商品的用户还购买了”等栏目，从而增加可观收益",
    "D. 某高校要求教师使用网上教学管理系统，录入学生的期末考试成绩，以便借助短信群发软件告知学生成绩"
   ],
   "answer": "D",
   "analysis": "第一步：找出定义关键词。\n“从大量的存储数据中利用统计、情报检索、模式识别、在线分析处理和专家系统（依靠过去的经验）等方法或技术”、“发现隐含在其中、事先不知道但又是潜在有用的信息和知识”。\n第二步：逐一分析选项。\nA项：上一年度消费者购物行为符合“对大量数据的统计、情报检索、在线分析处理的技术”，并且发现了“尿布img/formula-4d90d7a7e1165b03.webp啤酒”这一模式，符合“发现隐含在其中、事先不知道但又是潜在有用的信息”，符合题干定义，排除；\nB项：国际快递和物流公司运输的药品符合“大量的存储数据”；“无线射频识别”符合模式识别、在线分析等方法和技术；而“监控并调整其温度”符合“发现有用信息”这一关键词，符合题干定义，排除；\nC项：“购买该商品的用户还购买了”是通过以前购买过此图书的消费者还购买过其他商品的大量的数据分析而总结出来的，符合“对大量数据利用统计、情报检索”这一关键词，向客户推荐其他商品符合“隐含在其中，潜在有用信息”，符合题干定义，排除；\nD项：“录入学生的期末考试成绩，以便借助短信群发软件告知学生成绩”，告知学生成绩没有体现发现隐含在其中的信息，不符合题干定义，当选。\n本题为选非题，故正确答案为D。",
   "exam": "tianjin",
   "year": 2017
