   "question": "下列动物如果都只能归属一种门类，并且满足以下条件：\n（1）如果动物B不是鸟，那么动物A是哺乳动物\n（2）或者动物C是哺乳动物，或者动物A是哺乳动物\n（3）如果动物B不是鸟，那么动物D不是鱼\n（4）或者动物D是鱼，或者动物E不是昆虫\n（5）如果动物E不是昆虫，那么动物B不是鸟\n以下哪项如果为真，可以得出“动物C是哺乳动物”的结论？",
   "options": [
    "A. 动物D不是鱼",
    "B. 动物E是昆虫",
    "C. 动物B不是鸟",
    "D. 动物A是哺乳动物"
   ],
   "answer": "B",
   "analysis": "题干条件只有（2）与动物C有关，（2）条件为：动物C是哺乳动物或动物A是哺乳动物；\n根据否一推一，想要得出“动物C是哺乳动物”的结论，必须得到动物A不是哺乳动物；\n则根据（1），如果动物B不是鸟，得到动物A是哺乳动物，则无法推出“动物C是哺乳动物”的结论，因此须满足动物B是鸟；\n根据（5），如果动物E不是昆虫，则动物B不是鸟，无法推出结论，因此必须满足E是昆虫。\n故正确答案为B。",
   "exam": "tianjin",
   "year": 2019
