   "source": "2019年420联考《行测》题（天津卷） · 第32题",
   "question": "如今，基于互联网的新型科普方式层出不穷。浅阅读、视频直播以及游戏互动等方式，使得如今获取科学知识的渠道越来越多、门槛也越来越低。研究者认为，尽管“互联网+科普”令科学知识的获取和传播方式发生了很大变化，但这不是对科普传播的一种颠覆，而是显示了公民科学素养的提升。\n以下哪项如果为真，最能质疑研究者的观点？",
