   "module": "判断推理",
   "source": "2020年天津市公务员考试《行测》试题 · 第14题",
   "question": "直接歧视，是指某个行为具有直接的针对性，对于具备不同性别、种族、肤色、年龄以及其他非自我选择特征的人来说有显性的区别对待效果。间接歧视，是指某个看似中立，不针对任何人的行为，却实实在在地在具备不同性别、种族、肤色、年龄以及其他非自我选择特征的人之间造成了区别对待的结果。\n根据上述定义，下列属于间接歧视的是：",
   "options": [
    "A. 小王是某企业女职工，在一次升为部门经理的考核中，公司最后因为她性格过于柔软而拒绝对其升职",
    "B. 某企业要求所有员工都必须定期参加体能训练，后来企业女职工坚持不下来，纷纷离职，结果该企业成为了著名的“光棍”企业",
    "C. 消防队以便于防火为由，禁止消防队员留长发，导致的结果是基本上没有一线女性消防员",
    "D. 某企业以员工需要经常加班、对体力要求高为由，明确只招40周岁以下的劳动者入职"
   ],
   "answer": "B",
   "analysis": "第一步：找出定义关键词。\n直接歧视：“某个行为具有直接的针对性”、“不同性别、种族、肤色、年龄以及其他非自我选择特征的人”、“有显性的区别对待”；\n间接歧视：“某个看似中立,不针对任何人的行为”、“实实在在地在具备不同性别、种族、肤色、年龄以及其他非自我选择特征的人”、“造成了区别对待”；\n第二步：逐一分析选项。\nA项：公司以性格过于柔软为由拒绝小王升职，以性格限制，不符合“某个看似中立，不针对任何人的行为”，不符合“间接歧视”定义，排除； \nB项：某企业要求所有员工都必须定期参加体能训练，女员工坚持不下来选择离职，这看似男女平等的标准，因为男女生理条件的不同，实际上把绝大部分的女性排除在外，符合“某个看似中立，不针对任何人的行为”，也符合“实实在在地在具备不同性别、种族、肤色、年龄以及其他非自我选择特征的人”，符合“间接歧视”定义，当选；\nC项：消防队以便于防火为由，禁止消防队员留长发，禁止留长发的规定针对了大部分女性，不符合“某个看似中立，不针对任何人的行为”，女生可以选择留长发或短发，是自我选择特征，不符合“实实在在地在具备不同性别、种族、肤色、年龄以及其他非自我选择特征的人”，不符合“间接歧视”定义，排除；\nD项：企业以员工需要经常加班、对体力要求高为由拒绝40周岁及以上的劳动者，以年龄限制，不符合“某个看似中立，不针对任何人的行为”，不符合“间接歧视”定义，排除。\n故正确答案为B。",
   "exam": "tianjin",
   "year": 2020
