   "module": "判断推理",
   "source": "2021年天津市公务员考试《行测》题 · 第35题",
   "question": "长期生活不规律会导致免疫细胞和胆固醇积聚在血管壁上，变成粥样斑块。这些斑块破碎时会形成血栓，血栓有可能脱落，沿血管流动。由于牙周病菌是一种厌氧菌，而血管中有大量氧气，因此牙周病菌单独进入血管并不能存活。但是，因为免疫细胞能够有效隔绝血管中的氧气，所以人们认为牙周病菌能把免疫细胞当作交通工具，借此移动至身体各处。\n以下哪项如果为真，最能加强上述论证？",
   "options": [
    "A. 生活不规律会使体内产生大量胆固醇和厌氧菌",
    "B. 血栓脱落会导致血管不通顺阻碍牙周病菌移动",
    "C. 免疫细胞的整体内环境不会造成牙周病菌失活",
    "D. 牙周病菌对身体血管健康的影响是公认的"
   ],
   "answer": "C",
   "analysis": "第一步：找出论点和论据。\n论点：牙周病菌能把免疫细胞当作交通工具，借此移动至身体各处。\n论据：牙周病菌是一种厌氧菌，而血管中有大量氧气，免疫细胞能够有效隔绝血管中的氧气。\n本题论点讨论的是免疫细胞帮助牙周病菌移动至身体各处，论据讨论的是免疫细胞帮助牙周病菌隔绝血管中的氧气，都在讨论免疫细胞帮助牙周病菌移动，话题一致，且问法为“加强论证”，加强优先考虑必要条件。\n第二步：逐一分析选项。\nA项：论点说的是免疫细胞帮助牙周病菌移动至身体各处，该项说的是生活不规律的危害，话题不一致，无法加强，排除；\nB项：血栓脱落会导致血管不通顺阻碍牙周病菌移动，血栓阻碍了流通，那牙周病菌也无法移动，免疫细胞就无法帮助牙周病菌移动至身体各处，削弱项，无法加强，排除；\nC项：免疫细胞的整体内环境不会造成牙周病菌失活，如果免疫细胞的整体内环境会造成牙周病菌失活，那免疫细胞就无法帮助牙周病菌移动至身体各处，因此该项是题干结论能够成立的必要条件，可以加强，当选；\nD项：论点说的是免疫细胞帮助牙周病菌移动至身体各处，该项说的是牙周病菌对身体血管健康的影响，话题不一致，无法加强，排除。\n故正确答案为C。",
