   "source": "2022年天津市公务员录用考试《行测》试题 · 第10题",
   "question": "分系式是指在一个句法结构里至少有两个联合词组，这些联合词组的组成成分分别搭配，构成两套或两套以上平行的语法关系，表示两个或两个以上不同的意思。分别搭配是前一个联合结构里的并列成分依次分别跟后一个联合结构里的并列成分搭配，形成一种分系式的句法结构。\n根据上述定义，下列不属于分别搭配的是：",
   "options": [
    "A. 裘马轻肥",
    "B. 卖官鬻爵",
    "C. 吾盗天地之时利",
    "D. 井灶，人所饮食"
   ],
   "answer": "B",
   "analysis": "第一步：找出定义关键词。\n分系式：“两个联合词组”、“构成两套或两套以上平行的语法关系”；\n分别搭配：“前一个联合结构里的并列成分”、“分别跟后一个联合结构里的并列成分搭配”。\n第二步：逐一分析选项。\nA项：“裘马轻肥”根据“肥马轻裘”而来，意思为身上穿着软皮衣，骑着肥壮骏马，其中“轻裘”和“肥马”分别为联合词组，“裘”和“马”并列，二者搭配；“轻”和“肥”并列，二者搭配，从而形成句法结构“裘马轻肥”，符合“前一个联合结构里的并列成分”、“分别跟后一个联合结构里的并列成分搭配”，符合“分别搭配”定义，排除；\nB项：“卖官鬻爵”的意思是出卖官职爵位，其中“卖官”和“鬻爵”分别为联合词组，“卖”和“鬻”并列，“官”和“爵”并列，但两个联合词组中的并列成分并未搭配，不符合“前一个联合结构里的并列成分”、“分别跟后一个联合结构里的并列成分搭配”，不符合“分别搭配”定义，当选；\nC项：“吾盗天地之时利”根据“吾盗天之时，吾盗地之利”而来，的意思是我偷盗天时和地利，其中“天之时”和“地之利”分别为联合词组，“天”和“地”并列，二者搭配；“时”和“利”并列，二者搭配，从而形成句法结构“天地之时利”，符合“前一个联合结构里的并列成分”、“分别跟后一个联合结构里的并列成分搭配”，符合“分别搭配”定义，排除；\nD项：“井灶，人所饮食”根据“井，人所饮；灶，人所食”而来，意思是井是人打水喝的地方，灶台是人做饭吃的地方，其中“井，人所饮”和“灶，人所食”分别为联合词组，“井”和“灶”并列，二者搭配；“饮”和“食”并列，二者搭配，从而形成句法结构“井灶，人所饮食”，符合“前一个联合结构里的并列成分”、“分别跟后一个联合结构里的并列成分搭配”，符合“分别搭配”定义，排除。\n本题为选非题，故正确答案为B。",
   "exam": "tianjin",
   "year": 2022
