   "module": "判断推理",
   "source": "2024年天津市公务员录用考试《行测》题 · 第33题",
   "question": "与储存能量的白色脂肪细胞不同，棕色脂肪细胞会将能量以热的形式消耗掉。实验发现，正在死亡的棕色脂肪细胞会分泌出大量肌苷。接收到肌苷分子信号后，不仅周围的棕色细胞被激活，就连周围的白色脂肪细胞也被转化成棕色脂肪细胞。但是肌苷转运蛋白能将肌苷转至细胞内降低了细胞外的肌苷浓度，致使肌苷的“促燃”作用大打折扣。对照实验证实，喂食高能量饮食并同时使用肌苷转运蛋白抑制剂的小鼠仍然较瘦，且免受糖尿病的困扰。\n由此可以推出：",
   "options": [
    "A. 肌苷能调节棕色脂肪细胞在生物体中的产热过程",
    "B. 棕色脂肪细胞有助于身体维持体温，抵御寒冬",
    "C. 刺激棕色脂肪细胞，能够增加身体能量燃烧",
    "D. 干扰转运蛋白活性的物质可用于肥胖症治疗"
   ],
   "answer": "C",
   "analysis": "日常结论题，根据题干信息逐一分析选项。\nA项：根据第四句话“肌苷转运蛋白能将肌苷转至细胞内降低了细胞外的肌苷浓度，致使肌苷的‘促燃’作用大打折扣”可知，是“肌苷转运蛋白”可以调节产热过程，而不是“肌苷”，偷换概念，无法推出，排除；\nB项：根据第一句话“棕色脂肪细胞会将能量以热的形式消耗掉”可知，没有提及是否能维持体温，无中生有，无法推出，排除；\nC项：根据第一句话“棕色脂肪细胞会将能量以热的形式消耗掉”和第三句话“接收到肌苷分子信号后，不仅周围的棕色细胞被激活”可知，刺激棕色细胞后，棕色细胞会将能量燃烧，可以推出，当选；\nD项：题干讨论的是“肌苷转运蛋白”，但该项讨论的是“转运蛋白”，因此无法推出，排除。\n故正确答案为C。",
