   "question": "一级预防是指在疾病尚未发生时针对病因（或危险因素）所采取的措施，即“防病于未然”。一级预防包括健康促进和健康保护两方面内容，其中，健康促进是促使人们维护和改善他们自身健康的过程；健康保护是对有明确病因（或危险因素）或具备特异预防手段的疾病所采取的措施。\n根据上述定义，下列说法正确的是：",
